from datetime import datetime, timezone, timedelta
from decimal import Decimal
from ledgerly.models import Subscription
from ledgerly.subscriptions import prorated_refund
from ledgerly.errors import BillingError

T0 = datetime(2026,1,1,tzinfo=timezone.utc)
def sub(price="30.00", days=30, start=T0):
    return Subscription("s","c",Decimal(price),days,start)

# half period
print("half:", prorated_refund(sub(), datetime(2026,1,16,tzinfo=timezone.utc)))
# cancel at period start -> full refund
print("start:", prorated_refund(sub(), T0))
# cancel at period end -> 0
print("end:", prorated_refund(sub(), datetime(2026,1,31,tzinfo=timezone.utc)))
# multi-period: cancel in second period
print("2nd period half:", prorated_refund(sub(), datetime(2026,2,15,tzinfo=timezone.utc)))
# half-up rounding: 0.05 * 10% = 0.005 -> 0.01
print("half-up:", prorated_refund(sub("0.05",10), datetime(2026,1,10,tzinfo=timezone.utc)))
# before start
try:
    prorated_refund(sub(), datetime(2025,12,31,tzinfo=timezone.utc))
except BillingError as e: print("before_start:", e.code)
# invalid periods
for bad in [0,-1,True,"30",30.0]:
    try:
        prorated_refund(sub(days=bad), T0)
    except BillingError as e: print("invalid:", repr(bad), e.code)
# naive cancel
try:
    prorated_refund(sub(), datetime(2026,1,16))
except BillingError as e: print("naive:", e.code)
EOF"}

